  const url = `${GITHUB_API}/repos/${username}/${repo}/issues`;

  const response = await fetch(url, {
    method: 'POST',
    headers: authHeaders(context),
    body: JSON.stringify({
      title,
      body: body || '',
      ...args.extra
    })
  });

  if (!response.ok) {
    throw new Error(`Failed to create issue: ${response.status}`);
  }

  const issue = await response.json();

  return {
    number: issue.number,
    title: issue.title,
    url: issue.html_url,
    state: issue.state
  };
}

/**
 * Search repositories
 */
async function searchRepos(args, context) {
  const username = await getUsername(context);
  const { query, sort = 'updated', limit = 30 } = args;

  if (!query) {
    throw new Error('Search query required');
  }

  // Search user's repos
  const url = `${GITHUB_API}/search/repositories?q=${encodeURIComponent(query)}+user:${username}&sort=${sort}&per_page=${limit}`;

  const response = await fetch(url, { headers: authHeaders(context) });

  if (!response.ok) {
    throw new Error(`Search failed: ${response.status}`);
  }

  const data = await response.json();

  return {
    total: data.total_count,
    repos: data.items?.map(r => ({
      name: r.name,
      full_name: r.full_name,
      description: r.description,
      stars: r.stargazers_count,
      language: r.language,
      url: r.html_url
    })) || []
  };
}

// Skill definition
const skill = {
  name: 'github',
  version: '1.0.0',
  description: 'Query and manage GitHub repositories',

  actions: {
    list_repos: {
      description: 'List your repositories',
      parameters: {
        type: 'object',
        properties: {
          type: { type: 'string', enum: ['owner', 'all', 'member'], default: 'owner' },
          sort: { type: 'string', enum: ['created', 'updated', 'pushed', 'full_name'], default: 'updated' },
          language: { type: 'string' },
          limit: { type: 'number', default: 30 }
        }
      },
      handler: listRepos
    },

    get_repo: {
      description: 'Get repository details',
      parameters: {
        type: 'object',
        properties: {
          owner: { type: 'string' },
          repo: { type: 'string' }
        },
        required: ['owner', 'repo']
      },
      handler: getRepo
    },

    check_ci_status: {
      description: 'Check CI/CD pipeline status',
      parameters: {
        type: 'object',
        properties: {
          owner: { type: 'string' },
          repo: { type: 'string' }
        },
        required: ['owner', 'repo']
      },
      handler: checkCIStatus
    },

    get_recent_activity: {
      description: 'Get recent commits',
      parameters: {
        type: 'object',
        properties: {
          repo: { type: 'string' },
          limit: { type: 'number', default: 10 }
        },
        required: ['repo']
      },
